class Carnet:
    def __init__(self, distances):
        self.distances = list(distances)

    def moyenne(self):
        if not self.distances:
            raise ValueError("carnet vide")
        return sum(self.distances) / len(self.distances)

    def au_dessus(self, seuil):
        return [d for d in self.distances if d > seuil]

print(Carnet([12, 7.5, 20]).au_dessus(10))

check:
c = Carnet([12, 7.5, 20, 10]); assert c.au_dessus(10) == [12, 20]; assert c.distances == [12, 7.5, 20, 10]; assert Carnet([]).au_dessus(0) == []
try:
    Carnet([]).moyenne()
except ValueError:
    pass
else:
