solution:
import numpy as np
def normaliser(x,eps=1e-5):
    x=np.asarray(x,dtype=float)
    return (x-x.mean(-1,keepdims=True))/np.sqrt(x.var(-1,keepdims=True)+eps)

def bloc(x,attention,ffn,norm):
    h=x+attention(norm(x))
    return h+ffn(norm(h))

